SELECT ?zone ?uri ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label "DataCenter_bot_ZN_6" .
  ?zone ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}

SELECT ?sensor ?label ?point WHERE {
  ?zone rdfs:label "DataCenter_bot_ZN_6" .
  ?zone a brick:Zone .
  ?sensor brick:hasPoint ?point .
  OPTIONAL { ?sensor rdfs:label ?label }
  FILTER (a?sensor brick:ElectricPowerSensor || a?point brick:ElectricPower)
}

SELECT ?sensor ?point ?pointcls ?tsid WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07> }
  { 
    ?point brick:hasSubComponent ?zone .
    ?sensor brick:hasPoint ?point .
  }
  OPTIONAL { ?sensor a ?sensorcls }
  OPTIONAL { ?point a ?pointcls }
  OPTIONAL { ?sensor ref:hasExternalReference ?r ; ?r ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?point ?sensorcls ?tsid WHERE {
  ?sensor brick:hasPoint ?point .
  ?point brick:hasSubComponent <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07> .
  ?sensor a brick:ElectricPowerSensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?r }
  OPTIONAL { ?r ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?p ?pcls WHERE {
  ?s brick:hasPoint ?p .
  ?p brick:hasSubComponent <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07> .
  OPTIONAL { ?p a ?pcls }
}

SELECT ?s ?p ?pcls ?r ?tsid ?label WHERE {
  VALUES ?s { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07_Electric_Power_Sensor> }
  OPTIONAL { ?s brick:hasPoint ?p }
  OPTIONAL { ?p a ?pcls }
  OPTIONAL { ?s ref:hasExternalReference ?r }
  OPTIONAL { ?r ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p rdfs:label ?label }
}

